// Figma names (Nagarro-Icons, normalised 2026-10-13) → the keys above, which
// kept their original spellings so existing templates don't break.
export const ICON_ALIASES = {
  "applications-2": "applicaitons-2",
  "scissors": "sissors",
  "zig-zag-path": "ziz-zag-path",
  "shopping-cart-with-gear": "shoping-cart-with-gear",
  "graph-downwards": "downward-graph",
};

/**
 * Return inline SVG markup for a named icon.
 * @param {string} name  icon name (see ICONS keys / comment above)
 * @param {string} [cls] optional class added to the root <svg>
 * @returns {string} SVG markup, or "" if the name is unknown
 */
export function icon(name, cls = "") {
  const svg = ICONS[name] ?? ICONS[ICON_ALIASES[name]];
  if (!svg) {
    console.warn(`icon(): unknown icon name "${name}"`);
    return "";
  }
  return cls ? svg.replace("<svg ", `<svg class="${cls}" `) : svg;
}
